CREATE TABLE farm_plot (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE record_plot (record_id VARCHAR(36) NOT NULL, group_id VARCHAR(36) NOT NULL, plot_id VARCHAR(36) NOT NULL, group_name VARCHAR(80) NOT NULL, plot_name VARCHAR(80) NOT NULL, inputs_json LONGTEXT NOT NULL, PRIMARY KEY(record_id,group_id,plot_id));
INSERT INTO record_plot(record_id,group_id,plot_id,group_name,plot_name,inputs_json) SELECT record_id,group_id,'',group_name,'未指定地块',inputs_json FROM record_group;
INSERT INTO record_plot(record_id,group_id,plot_id,group_name,plot_name,inputs_json) SELECT r.id,'','','未分组','未指定地块',r.inputs_json FROM harvest_record r WHERE NOT EXISTS (SELECT 1 FROM record_plot p WHERE p.record_id=r.id);
CREATE TABLE dispatch_plan (id VARCHAR(36) PRIMARY KEY, work_date DATE NOT NULL, period VARCHAR(2) NOT NULL, worker_id VARCHAR(36) NOT NULL, group_id VARCHAR(36) NOT NULL, product_id VARCHAR(36) NOT NULL, plot_id VARCHAR(36) NOT NULL, resolution VARCHAR(20) NOT NULL DEFAULT '', reason VARCHAR(1000) NOT NULL DEFAULT '', destination LONGTEXT NOT NULL, version INT NOT NULL DEFAULT 1, created_by VARCHAR(36) NOT NULL, updated_by VARCHAR(36) NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX dispatch_date ON dispatch_plan(work_date);
CREATE TABLE dispatch_receipt (operation_id VARCHAR(36) PRIMARY KEY, actor_id VARCHAR(36) NOT NULL, request_hash VARCHAR(64) NOT NULL, result_json LONGTEXT NOT NULL);
CREATE TABLE import_batch (id VARCHAR(36) PRIMARY KEY, actor_id VARCHAR(36) NOT NULL, kind VARCHAR(20) NOT NULL, source_json LONGTEXT NOT NULL, preview_hash VARCHAR(64) NOT NULL, result_json LONGTEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE daily_print_snapshot (id VARCHAR(36) PRIMARY KEY, work_date DATE NOT NULL, group_id VARCHAR(36) NOT NULL, snapshot_json LONGTEXT NOT NULL, created_by VARCHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
